-- Post-lesson summary (2026-10-21): the teacher's message to the student after
-- a lesson — generated by AI from the lesson's songs, notes and homework,
-- editable, kept on the lesson for the student to read and e-mailed once.
-- Additive only: existing lesson RLS already lets the student read their
-- lesson row and only teachers/admins update it.

alter table public.lessons add column if not exists summary text;
alter table public.lessons add column if not exists summary_generated_at timestamptz;
alter table public.lessons add column if not exists summary_sent_at timestamptz;

comment on column public.lessons.summary is
  'Message to the student after the lesson (Polish, plain text). Generated by AI, editable by the teacher, shown to the student on the lesson page.';
comment on column public.lessons.summary_generated_at is 'When the summary was last generated or edited.';
comment on column public.lessons.summary_sent_at is 'When the summary was e-mailed to the student (null = never sent).';
